body.script:
//
    /* ================================================================
       KEY SYSTEM CONFIG — change these to match your repo files
    ================================================================ */
    var KEY_GATE_ENABLED = true;   // set to false to disable the lock entirely
    var KEY_LIST_URL   = 'https://cdn.jsdelivr.net/gh/carlosfnf/get-better@main/keys.txt';
    var CODEWORDS_URL  = 'https://cdn.jsdelivr.net/gh/carlosfnf/get-better@main/codewords.txt';
    var MASTER_KEY_URL = 'https://cdn.jsdelivr.net/gh/carlosfnf/get-better@main/master.txt';
    var KEYS_CACHE_KEY       = 'bb_keys_cache';
    var CODEWORDS_CACHE_KEY  = 'bb_codewords_cache';
    var MASTER_CACHE_KEY     = 'bb_master_cache';
    var ACCESS_COOKIE = 'bb_access';
    var ACCESS_LS     = 'bb_access_granted';
    var KEY_LIST_TTL  = 24 * 60 * 60 * 1000; // refresh cached key lists daily

    /* ================================================================
       GRADIENT TEXT DETECTION (replaces the @supports rule, which
       strict CSS validators reject). If supported, body gets the
       .grad-text class and the titles use the rainbow gradient;
       otherwise they stay clean white — never invisible.
    ================================================================ */
    (function detectGradientText() {
        try {
            var d = document.createElement('div');
            d.style.backgroundClip = 'text';
            d.style.webkitBackgroundClip = 'text';
            if (d.style.backgroundClip === 'text' || d.style.webkitBackgroundClip === 'text') {
                document.body.classList.add('grad-text');
            }
        } catch (e) {}
    })();

    /* ================================================================
       SEAMLESS LOADER (plain white glowing text — no gradient-clip,
       no @supports, no pseudo-elements anywhere)
    ================================================================ */
    const loaderOverlayDOM = `
    <style>
        #seamless-loader-overlay { position: fixed !important; top: 0 !important; left: 0 !important; width: 100vw !important; height: 100vh !important; background: radial-gradient(circle at 50% 45%, #16161f 0%, #050505 100%) !important; z-index: 2147483647 !important; display: flex !important; flex-direction: column !important; align-items: center !important; justify-content: center !important; transition: opacity 1.2s cubic-bezier(0.25, 0.8, 0.25, 1) !important; pointer-events: none !important; margin: 0 !important; padding: 0 !important; overflow: hidden !important; }
        .cool-spinner { position: relative !important; width: 120px !important; height: 120px !important; margin-bottom: 40px !important; animation: loader-in .6s cubic-bezier(.22,1,.36,1) both !important; }
        .cool-spinner div { position: absolute !important; box-sizing: border-box !important; border-radius: 50% !important; border: 4px solid transparent !important; animation: ring-spin 2s cubic-bezier(0.68, -0.55, 0.27, 1.55) infinite !important; }
        .cool-spinner div:nth-child(1) { width: 100% !important; height: 100% !important; top: 0 !important; left: 0 !important; border-top-color: #ff4757 !important; border-bottom-color: #ff6b81 !important; }
        .cool-spinner div:nth-child(2) { width: 80% !important; height: 80% !important; top: 10% !important; left: 10% !important; border-left-color: #6e8efb !important; border-right-color: #a777e3 !important; animation-direction: reverse !important; animation-duration: 1.5s !important; }
        .cool-spinner div:nth-child(3) { width: 60% !important; height: 60% !important; top: 20% !important; left: 20% !important; border-top-color: #ffffff !important; animation-duration: 1s !important; }
        @keyframes ring-spin { 0% { transform: rotate(0deg); } 100% { transform: rotate(360deg); } }
        .loader-text { font-family: 'Segoe UI', Tahoma, sans-serif !important; font-size: 1.8rem !important; font-weight: 800 !important; letter-spacing: 6px !important; text-transform: uppercase !important; color: #ffffff !important; text-shadow: 0 0 18px rgba(110,142,251,.65), 0 0 40px rgba(167,119,227,.4) !important; animation: loader-in .6s .15s both !important; }
        .loader-bar { width: 250px !important; max-width: 70vw !important; height: 4px !important; border-radius: 4px !important; background: rgba(255,255,255,0.1) !important; overflow: hidden !important; margin-top: 32px !important; position: relative !important; animation: loader-in .6s .3s both !important; }
        .loader-bar-slide { position: absolute !important; top: 0 !important; left: -45% !important; width: 45% !important; height: 100% !important; border-radius: 4px !important; background: linear-gradient(90deg, #ff4757, #a777e3, #6e8efb) !important; box-shadow: 0 0 14px rgba(110,142,251,0.9) !important; animation: bar-slide 1.2s cubic-bezier(.45,0,.55,1) infinite !important; }
        @keyframes bar-slide { 0% { left: -45%; } 100% { left: 100%; } }
        @keyframes loader-in { from { opacity: 0; transform: translateY(24px); } to { opacity: 1; transform: translateY(0); } }
    </style>
    <div id="seamless-loader-overlay">
        <div class="cool-spinner"><div></div><div></div><div></div></div>
        <div class="loader-text" id="dynamic-loader-text">LOADING...</div>
        <div class="loader-bar"><div class="loader-bar-slide"></div></div>
    </div>`;

    const loaderScript = `
    <script>
        window.addEventListener('load', function() {
            setTimeout(function() {
                var overlay = document.getElementById('seamless-loader-overlay');
                if(overlay) { overlay.style.opacity = '0'; setTimeout(function() { overlay.remove(); }, 1200); }
            }, 600);
        });
        setTimeout(function() {
            var overlay = document.getElementById('seamless-loader-overlay');
            if(overlay && overlay.style.opacity !== '0') { overlay.style.opacity = '0'; setTimeout(function() { overlay.remove(); }, 1200); }
        }, 4000);
    <\/script>`;

    function openSeamlessWindow(htmlContent, loadingMsg) {
        var newWindow = window.open('about:blank', '_blank');
        if(!newWindow) { alert("Popup blocked! Please allow popups for this site."); return; }

        var customLoaderDOM = loaderOverlayDOM.replace('LOADING...', loadingMsg);
        var initialHtml = '<!DOCTYPE html><html><head><title>Loading...</title></head><body style="margin:0; background:#050505;">' + customLoaderDOM + '</body></html>';
        newWindow.document.write(initialHtml);

        var finalHtml = htmlContent;
        var injection = customLoaderDOM + loaderScript;

        if (finalHtml.match(/<body[^>]*>/i)) {
            finalHtml = finalHtml.replace(/(<body[^>]*>)/i, '$1' + injection);
        } else if (finalHtml.includes('</head>')) {
            finalHtml = finalHtml.replace('</head>', '</head>' + injection);
        } else {
            finalHtml = injection + finalHtml;
        }

        setTimeout(function() {
            newWindow.document.open();
            newWindow.document.write(finalHtml);
            newWindow.document.close();

            setTimeout(function() {
                var clonedSplash = newWindow.document.getElementById('splash-screen');
                if (clonedSplash) clonedSplash.remove();
            }, 50);
        }, 1200);
    }

    /* ================================================================
       SILENT BACKGROUND PRE-CACHER
    ================================================================ */
    function preCacheGames() {
        console.log("Starting silent background pre-cache...");
        var buttons = document.querySelectorAll('.game-btn');
        buttons.forEach(function(btn) {
            var gameUrl = btn.getAttribute('data-url');
            if (!localStorage.getItem('cache_' + gameUrl)) {
                fetch(gameUrl)
                    .then(r => r.text())
                    .then(htmlCode => {
                        try {
                            localStorage.setItem('cache_' + gameUrl, htmlCode);
                            console.log("Successfully cached for offline use: " + gameUrl);
                            updateCacheCount();
                        } catch (e) {
                            console.warn("Storage limit reached for Chromebook. Could not cache: " + gameUrl);
                        }
                    })
                    .catch(err => {
                        console.log("Offline or network block. Could not pre-cache: " + gameUrl);
                    });
            }
        });
    }
    window.addEventListener('load', preCacheGames);

    /* ================================================================
       KEY SYSTEM
       --------------------------------------------------------------
       master.txt    : ONE base64-encoded master ID (line 1).
                       Matches the typed ID exactly -> instant
                       access from any IP. Checked FIRST.
       keys.txt      : one base64 value per line (line = ID).
                       IP key -> only that network unlocks;
                       codeword -> unlocks anywhere.
       codewords.txt : plain words, one per line.
    ================================================================ */
    function withTimeout(promise, ms) {
        return new Promise(function (resolve, reject) {
            var t = setTimeout(function () { reject(new Error('timeout')); }, ms);
            promise.then(function (v) { clearTimeout(t); resolve(v); },
                         function (e) { clearTimeout(t); reject(e); });
        });
    }

    function fetchTextNow(url) {
        var sep = url.indexOf('?') > -1 ? '&' : '?';
        return fetch(url + sep + 't=' + Date.now()).then(function (r) {
            if (!r.ok) throw new Error('HTTP ' + r.status);
            return r.text();
        });
    }

    function loadKeyFile(cacheKey, url) {
        var entry = null;
        try { entry = JSON.parse(localStorage.getItem(cacheKey) || 'null'); } catch (e) {}
        if (entry && entry.data && (Date.now() - (entry.t || 0)) < KEY_LIST_TTL) {
            return Promise.resolve(entry.data);
        }
        return fetchTextNow(url).then(function (txt) {
            try { localStorage.setItem(cacheKey, JSON.stringify({ t: Date.now(), data: txt })); } catch (e) {}
            return txt;
        }).catch(function (err) {
            if (entry && entry.data) return entry.data; // stale cache beats nothing when offline
            throw err;
        });
    }

    function parseKeyLines(txt) {
        txt = String(txt || '').replace(/\r/g, '').replace(/\s+$/, '');
        if (!txt) return [];
        return txt.split('\n');
    }

    function decodeKeyLine(line) {
        try { return decodeURIComponent(escape(window.atob(String(line).trim()))); }
        catch (e) { try { return window.atob(String(line).trim()); } catch (e2) { return null; } }
    }

    function getMyIp() {
        function viaIpify() {
            return fetch('https://api.ipify.org?format=json')
                .then(function (r) { return r.json(); })
                .then(function (d) { return d && d.ip; });
        }
        function viaIpapi() {
            return fetch('https://ipapi.co/json/')
                .then(function (r) { return r.json(); })
                .then(function (d) { return d && d.ip; });
        }
        return withTimeout(viaIpify().catch(function () { return viaIpapi(); }), 8000);
    }

    /* ---------- access persistence (cookie + localStorage mirror) ---------- */
    function setCookie(name, value, days) {
        try {
            var d = new Date();
            d.setTime(d.getTime() + (days * 24 * 60 * 60 * 1000));
            document.cookie = name + '=' + value + '; expires=' + d.toUTCString() + '; path=/; SameSite=Lax';
        } catch (e) {}
    }
    function getCookie(name) {
        try {
            var parts = document.cookie.split(';');
            for (var i = 0; i < parts.length; i++) {
                var c = parts[i];
                while (c.charAt(0) === ' ') c = c.substring(1);
                if (c.indexOf(name + '=') === 0) return c.substring(name.length + 1);
            }
        } catch (e) {}
        return null;
    }
    function grantAccess(id) {
        var payload = '';
        try { payload = window.btoa(id + '|' + Date.now()); } catch (e) { payload = String(id); }
        setCookie(ACCESS_COOKIE, payload, 365);
        try { localStorage.setItem(ACCESS_LS, payload); } catch (e) {}
    }
    function hasAccess() {
        var v = null;
        try { v = localStorage.getItem(ACCESS_LS); } catch (e) {}
        if (!v) v = getCookie(ACCESS_COOKIE);
        return !!v;
    }
    function revokeAccess() {
        setCookie(ACCESS_COOKIE, '', -1);
        try { localStorage.removeItem(ACCESS_LS); } catch (e) {}
    }

    /* ---------- gate UI ---------- */
    var gateFails = 0, gateLockUntil = 0, gateLockTimer = null;

    function setGateStatus(type, msg) {
        var el = document.getElementById('gate-status');
        if (!el) return;
        el.className = 'gate-status' + (type ? ' ' + type : '');
        el.textContent = msg;
    }

    function shakeGate() {
        var card = document.getElementById('gate-card');
        if (!card) return;
        card.classList.remove('shake');
        void card.offsetWidth;
        card.classList.add('shake');
    }

    function lockGate(seconds) {
        gateLockUntil = Date.now() + seconds * 1000;
        var input = document.getElementById('gate-input');
        var btn = document.getElementById('gate-submit');
        if (input) input.disabled = true;
        if (btn) btn.disabled = true;
        if (gateLockTimer) clearInterval(gateLockTimer);
        gateLockTimer = setInterval(function () {
            var left = Math.ceil((gateLockUntil - Date.now()) / 1000);
            if (left <= 0) {
                clearInterval(gateLockTimer); gateLockTimer = null;
                gateFails = 0;
                if (input) input.disabled = false;
                if (btn) btn.disabled = false;
                setGateStatus('', 'You may try again.');
                return;
            }
            setGateStatus('deny', 'Too many attempts. Retry in ' + left + 's');
        }, 250);
    }

    function gateFail(msg) {
        gateFails++;
        setGateStatus('deny', msg);
        shakeGate();
        if (gateFails >= 5) lockGate(30);
    }

    function gateSuccess(id, isMaster) {
        var card = document.getElementById('gate-card');
        var lock = document.getElementById('gate-lock');
        var btn = document.getElementById('gate-submit');
        if (btn) btn.disabled = true;
        if (card) card.classList.add('granted');
        if (lock) lock.textContent = '🔓';
        setGateStatus('ok', isMaster ? 'MASTER ACCESS GRANTED ✓' : 'ACCESS GRANTED ✓');
        grantAccess(id);
        document.body.classList.add('gate-passed');
        setTimeout(function () {
            hideGate();
            replaySplash();
        }, 1000);
    }

    function hideGate() {
        var gate = document.getElementById('gate-overlay');
        if (!gate) return;
        gate.classList.add('hide');
        setTimeout(function () {
            gate.classList.remove('show');
            gate.classList.remove('hide');
            gate.style.display = 'none';
        }, 650);
    }

    function attemptUnlock() {
        if (Date.now() < gateLockUntil) return;
        var input = document.getElementById('gate-input');
        var btn = document.getElementById('gate-submit');
        var raw = input ? input.value : '';
        var idNum = parseInt(raw, 10);

        if (!/^[0-9]+$/.test(raw.trim()) || idNum < 1) { gateFail('Enter a valid ID number.'); return; }

        setGateStatus('checking', 'VERIFYING...');
        if (btn) btn.disabled = true;

        // ---- STEP 1: MASTER KEY (checked first, works from any IP) ----
        loadKeyFile(MASTER_CACHE_KEY, MASTER_KEY_URL)
            .catch(function () { return ''; })
            .then(function (masterTxt) {
                var masterVal = decodeKeyLine(parseKeyLines(masterTxt)[0] || '');
                if (masterVal !== null && masterVal.trim() !== '' && masterVal.trim() === raw.trim()) {
                    if (btn) btn.disabled = false;
                    gateSuccess('master', true);
                    return;
                }
                // ---- STEP 2: normal ID line check ----
                return normalKeyCheck(raw, idNum, btn);
            })
            .catch(function () {
                if (btn) btn.disabled = false;
                gateFail('Could not load the key list. Check connection.');
            });
    }

    function normalKeyCheck(raw, idNum, btn) {
        return Promise.all([
            loadKeyFile(KEYS_CACHE_KEY, KEY_LIST_URL),
            loadKeyFile(CODEWORDS_CACHE_KEY, CODEWORDS_URL).catch(function () { return ''; }),
            getMyIp().catch(function () { return null; })
        ]).then(function (res) {
            var lines = parseKeyLines(res[0]);
            var words = parseKeyLines(res[1]);
            var myIp = res[2];
            if (btn) btn.disabled = false;

            if (idNum > lines.length) return gateFail('Invalid ID.');
            var rawLine = (lines[idNum - 1] || '').trim();
            if (!rawLine) return gateFail('Invalid ID.');

            var decoded = decodeKeyLine(rawLine);
            var candidates = [];
            if (decoded !== null && decoded.trim() !== '') candidates.push(decoded.trim());
            candidates.push(rawLine);

            var isWord = false, ipMatch = false, looksLikeIp = false;
            for (var ci = 0; ci < candidates.length; ci++) {
                var cand = candidates[ci];
                for (var wi = 0; wi < words.length; wi++) {
                    if (words[wi].trim().toLowerCase() === cand.toLowerCase()) { isWord = true; break; }
                }
                if (myIp && cand === myIp) ipMatch = true;
                if (/^(\d{1,3}\.){3}\d{1,3}$/.test(cand)) looksLikeIp = true;
            }

            if (isWord || ipMatch) return gateSuccess(idNum, false);
            if (!myIp && looksLikeIp) return gateFail('Could not verify your network — try again.');
            return gateFail('Access denied.');
        });
    }

    function replaySplash() {
        var splash = document.getElementById('splash-screen');
        if (!splash) return;
        var els = [splash].concat(
            Array.prototype.slice.call(splash.querySelectorAll('.ltr, .splash-sub, .launch-wrap'))
        );
        els.forEach(function (el) {
            el.style.animation = 'none';
            void el.offsetWidth;
            el.style.animation = '';
        });
    }

    function initGate() {
        if (!KEY_GATE_ENABLED) return;
        if (document.body.classList.contains('gate-passed')) return; // cloned-window shortcut
        if (hasAccess()) { document.body.classList.add('gate-passed'); return; }
        var gate = document.getElementById('gate-overlay');
        if (!gate) return;
        gate.classList.add('show');
        setTimeout(function () {
            var input = document.getElementById('gate-input');
            if (input) input.focus();
        }, 450);
        var btn = document.getElementById('gate-submit');
        if (btn) btn.addEventListener('click', attemptUnlock);
        var gateInput = document.getElementById('gate-input');
        if (gateInput) {
            gateInput.addEventListener('keyup', function (e) {
                if (e.key === 'Enter' || e.keyCode === 13) attemptUnlock();
            });
            gateInput.addEventListener('input', function () {
                this.value = this.value.replace(/[^0-9]/g, '');
            });
        }
    }

    /* ================================================================
       LETTER SPLIT
    ================================================================ */
    function splitLetters(el) {
        if (!el || el.dataset.split) return;
        el.dataset.split = '1';
        var text = el.textContent;
        el.textContent = '';
        var n = 0;
        for (var i = 0; i < text.length; i++) {
            var ch = text.charAt(i);
            if (ch === ' ') { el.appendChild(document.createTextNode(' ')); continue; }
            var ltr = document.createElement('span');
            ltr.className = 'ltr';
            ltr.textContent = ch;
            ltr.style.setProperty('--i', n);
            ltr.style.setProperty('--d', (450 + n * 45) + 'ms');
            el.appendChild(ltr);
            n++;
        }
    }
    try {
        splitLetters(document.getElementById('splash-title'));
        splitLetters(document.getElementById('main-title'));
    } catch (e) {}

    /* ================================================================
       SPLASH STARFIELD
    ================================================================ */
    function initStars() {
        var c = document.getElementById('splash-stars');
        if (!c || c.dataset.init) return;
        c.dataset.init = '1';
        for (var i = 0; i < 70; i++) {
            var star = document.createElement('span');
            star.className = 'star';
            var sz = (Math.random() * 2.2 + 1).toFixed(1);
            star.style.width = sz + 'px';
            star.style.height = sz + 'px';
            star.style.left = (Math.random() * 100).toFixed(2) + '%';
            star.style.top = (Math.random() * 100).toFixed(2) + '%';
            star.style.setProperty('--td', (1.6 + Math.random() * 3).toFixed(2) + 's');
            star.style.setProperty('--tl', (Math.random() * 4).toFixed(2) + 's');
            c.appendChild(star);
        }
        for (var j = 0; j < 2; j++) {
            var sh = document.createElement('span');
            sh.className = 'shooting-star';
            sh.style.top = (Math.random() * 35 + 5).toFixed(1) + '%';
            sh.style.left = (Math.random() * 35 + 5).toFixed(1) + '%';
            sh.style.animationDelay = (1.5 + j * 3.8) + 's';
            c.appendChild(sh);
        }
    }
    try { initStars(); } catch (e) {}

    /* ================================================================
       SHINE SPANS — real elements instead of pseudo-elements.
       Guarded so the cloned popout window never gets doubles.
    ================================================================ */
    (function injectShine() {
        var btns = document.querySelectorAll('.launch-btn, .game-btn');
        for (var i = 0; i < btns.length; i++) {
            var btn = btns[i];
            if (btn.querySelector('.shine')) continue;
            var shine = document.createElement('span');
            shine.className = 'shine';
            btn.appendChild(shine);
        }
    })();

    /* ================================================================
       GAME BUTTONS
    ================================================================ */
    var gameButtons = document.querySelectorAll('.game-btn');
    gameButtons.forEach(function (btn, i) {
        var delay = 700 + i * 85;
        btn.style.setProperty('--d', delay + 'ms');
        btn.style.setProperty('--fdelay', (delay + 800) + 'ms');
        btn.style.setProperty('--fd', (4 + Math.random() * 3).toFixed(2) + 's');

        btn.addEventListener('mousemove', function (e) {
            var r = this.getBoundingClientRect();
            var x = (e.clientX - r.left) / r.width;
            var y = (e.clientY - r.top) / r.height;
            this.style.setProperty('--mx', (x * 100).toFixed(1) + '%');
            this.style.setProperty('--my', (y * 100).toFixed(1) + '%');
            this.style.transform = 'perspective(700px) rotateX(' + ((y - 0.5) * -10).toFixed(2) + 'deg) rotateY(' + ((x - 0.5) * 12).toFixed(2) + 'deg) translateY(-6px) scale(1.03)';
        });
        btn.addEventListener('mouseleave', function () { this.style.transform = ''; });

        btn.addEventListener('click', function (e) {
            this.style.transform = '';
            var rect = this.getBoundingClientRect();
            var ripple = document.createElement('span');
            ripple.className = 'ripple';
            var size = Math.max(rect.width, rect.height) * 2.2;
            ripple.style.width = ripple.style.height = size + 'px';
            ripple.style.left = (e.clientX - rect.left - size / 2) + 'px';
            ripple.style.top = (e.clientY - rect.top - size / 2) + 'px';
            this.appendChild(ripple);
            setTimeout(function () { ripple.remove(); }, 700);
        });
    });

    /* ================================================================
       LAUNCH TRIGGERS
    ================================================================ */
    document.getElementById('launch-app-btn').addEventListener('click', function() {
        document.body.classList.add('ui-in');
        var fullDashboardHTML = '<!DOCTYPE html>\n' + document.querySelector('html').outerHTML;

        var splash = document.getElementById('splash-screen');
        splash.classList.add('splash-out');
        setTimeout(function() { splash.style.display = 'none'; }, 700);

        openSeamlessWindow(fullDashboardHTML, 'PLEASE WAIT');
    });

    gameButtons.forEach(function(btn) {
        btn.addEventListener('click', function() {
            btn.style.transform = '';
            var gameUrl = btn.getAttribute('data-url');
            var cachedHtml = localStorage.getItem('cache_' + gameUrl);
            var baseUrlPath = gameUrl.substring(0, gameUrl.lastIndexOf('/') + 1);
            var baseTag = `<base href="${baseUrlPath}">`;

            if (cachedHtml) {
                openSeamlessWindow(baseTag + cachedHtml, 'LAUNCHING GAME...');
            } else {
                var newWindow = window.open('about:blank', '_blank');
                if(!newWindow) return alert("Popup blocked! Allow popups.");

                var customLoaderDOM = loaderOverlayDOM.replace('LOADING...', 'FETCHING DATA...');
                newWindow.document.write('<!DOCTYPE html><html><head><title>Loading...</title></head><body style="margin:0; background:#050505;">' + customLoaderDOM + '</body></html>');

                fetch(gameUrl)
                    .then(r => r.text())
                    .then(htmlCode => {
                        try { localStorage.setItem('cache_' + gameUrl, htmlCode); updateCacheCount(); } catch(e){}
                        var finalHtml = htmlCode;
                        var injection = customLoaderDOM.replace('FETCHING DATA...', 'LAUNCHING GAME...') + loaderScript;

                        if (finalHtml.includes('<head>')) {
                            finalHtml = finalHtml.replace('<head>', '<head>' + baseTag);
                        }

                        if (finalHtml.match(/<body[^>]*>/i)) {
                            finalHtml = finalHtml.replace(/(<body[^>]*>)/i, '$1' + injection);
                        } else {
                            finalHtml = injection + finalHtml;
                        }

                        setTimeout(() => {
                            newWindow.document.open();
                            newWindow.document.write(finalHtml);
                            newWindow.document.close();
                        }, 800);
                    })
                    .catch(err => {
                        newWindow.document.open();
                        newWindow.document.write('<body style="background:black;color:red;display:flex;justify-content:center;align-items:center;height:100vh;font-family:sans-serif;"><h1>FAILED TO LOAD GAME. CHECK CONNECTION.</h1></body>');
                        newWindow.document.close();
                    });
            }
        });
    });

    /* ================================================================
       UI, SETTINGS & EFFECTS
    ================================================================ */
    var bgAudio = document.getElementById('bg-audio');
    document.body.addEventListener('click', function() {
        if (bgAudio.src && bgAudio.paused) bgAudio.play().catch(e => {});
    }, { once: true });

    function filterGames() {
        var query = document.getElementById('searchBar').value.toLowerCase();
        gameButtons.forEach(function(btn) {
            btn.style.display = btn.innerText.toLowerCase().includes(query) ? "block" : "none";
        });
    }

    document.getElementById('searchBar').addEventListener('animationend', function (e) {
        if (e.animationName === 'rise-in') this.classList.add('entered');
    });

    (function typePlaceholder() {
        var el = document.getElementById('searchBar');
        if (!el) return;
        var text = 'Search quick access games...';
        var i = 0;
        function tick() {
            el.setAttribute('placeholder', text.slice(0, i) + (i < text.length ? '_' : ''));
            if (i <= text.length) { i++; setTimeout(tick, 55); }
            else { setTimeout(function () { i = 0; tick(); }, 4200); }
        }
        tick();
    })();

    var settingsMenu = document.getElementById('settings-menu');
    var settingsBackdrop = document.getElementById('settings-backdrop');
    function toggleSettings(show) {
        settingsMenu.classList.toggle('open', show);
        settingsBackdrop.classList.toggle('open', show);
    }
    document.addEventListener('keydown', function (e) {
        if (e.key === 'Escape') toggleSettings(false);
    });

    var currentSnowPng = "data:image/svg+xml;utf8,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' stroke='rgba(255,255,255,0.9)' stroke-width='2' stroke-linecap='round'%3E%3Cpath d='M12 2v20M2 12h20M5 5l14 14M5 19L19 5'/%3E%3C/svg%3E";
    var videoBackground = document.getElementById('video-background');

    function saveSettings() {
        var bgUrl = document.getElementById('bg-input').value;
        var snowUrl = document.getElementById('snow-input').value;
        var audioFileInput = document.getElementById('audio-file-input');

        if (bgUrl.trim() !== "") {
            if (bgUrl.toLowerCase().endsWith('.mp4') || bgUrl.toLowerCase().endsWith('.webm')) {
                videoBackground.src = bgUrl; videoBackground.style.display = 'block'; document.body.style.backgroundImage = 'none';
            } else {
                document.body.style.backgroundImage = 'url("' + bgUrl + '")';
                document.body.style.backgroundSize = 'cover'; document.body.style.backgroundPosition = 'center';
                videoBackground.style.display = 'none';
            }
        }
        if (snowUrl.trim() !== "") currentSnowPng = snowUrl;

        if (audioFileInput.files && audioFileInput.files[0]) {
            bgAudio.src = URL.createObjectURL(audioFileInput.files[0]);
            bgAudio.play().catch(e => {});
        }
        toggleSettings(false);
    }

    /* ================================================================
       SNOW
    ================================================================ */
    function spawnSnowflake() {
        var container = document.getElementById('snow-container');
        if (!container) return;
        var flake = document.createElement('img');
        flake.src = currentSnowPng;
        flake.classList.add('snowflake');

        var depth = Math.random();
        var size = 7 + depth * 22;
        var dur = 12.5 - depth * 6;
        flake.style.width = size.toFixed(1) + 'px';
        flake.style.height = size.toFixed(1) + 'px';
        flake.style.left = (Math.random() * 100).toFixed(2) + 'vw';
        flake.style.setProperty('--sway', ((Math.random() * 36 + 12) * (Math.random() < 0.5 ? -1 : 1)).toFixed(0) + 'px');
        flake.style.setProperty('--o', (0.25 + depth * 0.6).toFixed(2));
        flake.style.setProperty('--fdur', dur.toFixed(2) + 's');
        flake.style.filter = 'blur(' + ((1 - depth) * 1.4).toFixed(2) + 'px) drop-shadow(0 0 5px rgba(255,255,255,.7))';
        if (Math.random() < 0.35) {
            flake.classList.add('twinkle');
            flake.style.setProperty('--tdur', (1.2 + Math.random() * 1.4).toFixed(2) + 's');
        }
        container.appendChild(flake);
        setTimeout(function() { flake.remove(); }, dur * 1000 + 400);
    }

    if (!window.snowIntervalStarted) {
        for (var s = 0; s < 8; s++) setTimeout(spawnSnowflake, s * 120);
        setInterval(spawnSnowflake, 350);
        window.snowIntervalStarted = true;
    }

    /* ================================================================
       MOUSE GLOW + PARALLAX
    ================================================================ */
    (function () {
        var glow = document.getElementById('mouse-glow');
        var ui = document.querySelector('.ui-container');
        var tx = window.innerWidth / 2, ty = window.innerHeight / 2, gx = tx, gy = ty;
        var tax = 0, tay = 0, pax = 0, pay = 0;
        window.addEventListener('mousemove', function (e) {
            tx = e.clientX; ty = e.clientY;
            tax = e.clientX / window.innerWidth - 0.5;
            tay = e.clientY / window.innerHeight - 0.5;
        });
        (function loop() {
            gx += (tx - gx) * 0.09;
            gy += (ty - gy) * 0.09;
            pax += (tax - pax) * 0.05;
            pay += (tay - pay) * 0.05;
            if (glow) glow.style.transform = 'translate(' + (gx - 200).toFixed(1) + 'px,' + (gy - 200).toFixed(1) + 'px)';
            if (ui) ui.style.transform = 'translate(' + (pax * 18).toFixed(2) + 'px,' + (pay * 12).toFixed(2) + 'px)';
            requestAnimationFrame(loop);
        })();
    })();

    /* ================================================================
       CACHE MANAGEMENT (Options menu)
    ================================================================ */
    function cachedGameCount() {
        var n = 0;
        try {
            for (var i = 0; i < localStorage.length; i++) {
                var k = localStorage.key(i);
                if (k && k.indexOf('cache_') === 0) n++;
            }
        } catch (e) {}
        return n;
    }

    function updateCacheCount() {
        var el = document.getElementById('cache-count');
        if (el) el.textContent = '(' + cachedGameCount() + ' cached)';
    }

    function clearGameCache() {
        var removed = 0;
        try {
            var doomed = [];
            for (var i = 0; i < localStorage.length; i++) {
                var k = localStorage.key(i);
                if (k && (k.indexOf('cache_') === 0 || k === KEYS_CACHE_KEY || k === CODEWORDS_CACHE_KEY || k === MASTER_CACHE_KEY)) doomed.push(k);
            }
            for (var j = 0; j < doomed.length; j++) { localStorage.removeItem(doomed[j]); removed++; }
        } catch (e) {}
        updateCacheCount();
        return removed;
    }

    function flashButtonState(btn, msg) {
        if (!btn) return;
        var old = btn.textContent;
        btn.textContent = msg;
        btn.disabled = true;
        setTimeout(function () { btn.textContent = old; btn.disabled = false; }, 1800);
    }

    (function initCacheControls() {
        var resetBtn = document.getElementById('reset-cache-btn');
        var accessBtn = document.getElementById('reset-access-btn');
        if (resetBtn) resetBtn.addEventListener('click', function () {
            var n = cachedGameCount();
            var extra = 0;
            try {
                if (localStorage.getItem(KEYS_CACHE_KEY)) extra++;
                if (localStorage.getItem(CODEWORDS_CACHE_KEY)) extra++;
                if (localStorage.getItem(MASTER_CACHE_KEY)) extra++;
            } catch (e) {}
            if (n + extra === 0) { flashButtonState(resetBtn, 'CACHE ALREADY EMPTY'); return; }
            if (window.confirm('Clear ' + n + ' cached game(s)' + (extra ? ' + cached key lists' : '') + '? Games will re-download on next launch.')) {
                var removed = clearGameCache();
                flashButtonState(resetBtn, 'CLEARED ' + removed + ' ✓');
            }
        });
        if (accessBtn) accessBtn.addEventListener('click', function () {
            if (window.confirm('Reset the access key on this device? You will need to re-enter a valid ID next time you open this page.')) {
                revokeAccess();
                flashButtonState(accessBtn, 'ACCESS RESET ✓');
            }
        });
        updateCacheCount();
    })();

    /* ================================================================
       KEY GENERATOR (owner tool) — type an IP or word, get base64
    ================================================================ */
    function copyToClipboard(text) {
        var out = document.getElementById('keygen-output');
        function done() {
            if (out) {
                out.classList.add('copied');
                setTimeout(function () { out.classList.remove('copied'); }, 1200);
            }
        }
        if (navigator.clipboard && navigator.clipboard.writeText) {
            navigator.clipboard.writeText(text).then(done, function () { legacyCopy(text, done); });
        } else {
            legacyCopy(text, done);
        }
    }
    function legacyCopy(text, done) {
        var ta = document.createElement('textarea');
        ta.value = text;
        ta.style.position = 'fixed'; ta.style.left = '-9999px';
        document.body.appendChild(ta);
        ta.select();
        try { if (document.execCommand('copy')) done(); } catch (e) {}
        document.body.removeChild(ta);
    }

    (function initKeygen() {
        var input = document.getElementById('keygen-input');
        var out = document.getElementById('keygen-output');
        if (!input || !out) return;
        input.addEventListener('input', function () {
            var v = input.value.trim();
            if (!v) { out.textContent = '—'; out.classList.remove('copied'); return; }
            try { out.textContent = window.btoa(v); }
            catch (e) { out.textContent = '(remove special characters)'; }
        });
        out.addEventListener('click', function () {
            var t = out.textContent;
            if (!t || t === '—' || t.charAt(0) === '(') return;
            copyToClipboard(t);
        });
    })();

    /* ================================================================
       START THE GATE
    ================================================================ */
    try { initGate(); } catch (e) { console.warn('Gate init failed, allowing access.', e); }
